
const id=location.hash.slice(1);if(!/^[a-f0-9-]{36}$/.test(id))throw new Error('Invalid session');const ch=new BroadcastChannel('bytequest-native-'+id);let busy=false;const close=()=>{ch.close();window.close();};document.getElementById('stop').onclick=()=>{ch.postMessage({type:'error',message:'Compiler stopped.'});close();};setTimeout(()=>{ch.postMessage({type:'error',message:'Compiler timed out.'});close();},115000);try{if(!crossOriginIsolated)throw new Error('Compiler isolation is not ready. Close this tab and try Run again.');const {headlessRunCode}=await import('https://cdn.jsdelivr.net/npm/@runno/runtime@0.10.3/dist/main.js');ch.onmessage=async e=>{if(e.data?.type==='close'){close();return;}if(e.data?.type!=='run'||busy||!['python','clang','clangpp'].includes(e.data.runtime)||typeof e.data.program!=='string'||e.data.program.length>1000000)return;busy=true;document.getElementById('status').textContent='Compiling and executing '+e.data.runtime+'…';try{const r=await headlessRunCode(e.data.runtime,e.data.program);ch.postMessage({type:'result',result:{resultType:r.resultType,exitCode:r.exitCode,stdout:(r.stdout||'').slice(-200000),stderr:(r.stderr||'').slice(0,12000),error:r.error}});}catch(e){ch.postMessage({type:'error',message:e.message});}};ch.postMessage({type:'ready'});}catch(e){document.getElementById('status').textContent=e.message;ch.postMessage({type:'error',message:e.message});}
